import * as React from "react";

export function ScrollVelocitySkew({ text = "Velocity Skew", className = "" }: { text?: string; className?: string }): React.JSX.Element {
  const [skew, setSkew] = React.useState(0);
  const lastY = React.useRef(0);
  React.useEffect(() => {
    const onScroll = () => {
      const vel = window.scrollY - lastY.current;
      lastY.current = window.scrollY;
      setSkew(Math.max(-20, Math.min(20, vel * 0.5)));
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);
  React.useEffect(() => { const id = setInterval(() => setSkew(p => p * 0.9), 16); return () => clearInterval(id); }, []);
  return (
    <div className={`select-none overflow-hidden ${className}`}>
      <span className="font-display font-black text-5xl text-ink inline-block" style={{ transform: `skewX(${skew}deg)`, transition: "transform 0.05s linear" }}>
        {text}
      </span>
    </div>
  );
}

import * as React from "react";
import { ScrollVelocitySkew } from "./scroll-velocity-skew";

export default function ScrollVelocitySkewDemo(): React.JSX.Element {
  return (
    <div className="flex min-h-[360px] w-full items-center justify-center rounded-2xl bg-neutral-950 p-8 border border-neutral-800">
      <ScrollVelocitySkew
        text="Next Generation Web Interfaces"
        className="text-3xl sm:text-5xl font-mono font-bold tracking-tight text-white text-center"
      />
    </div>
  );
}
